import { action } from "solid-js";
const assign = Object.assign;
const { defineProperty } = Object;
const bound = Object.assign.bind(null, {});
const target = {};
export const make = (source) => [
  assign({}, source),
  Object.assign.call(null, [], source),
  Reflect.apply(Object.assign, null, [new Map(), source]),
  Object.assign.apply(null, [function () {}, source]),
  defineProperty({}, "x", { get() { return 1; } }),
  bound(source),
  assign(target, source),
  Object.create(null),
];
void action;
